function clipSeg(m, b, xmin, xmax, ymin, ymax) {
  var lo = xmin, hi = xmax;
  if (Math.abs(m) > 1e-9) {
    var xa = (ymin - b) / m, xb = (ymax - b) / m;
    lo = Math.max(lo, Math.min(xa, xb));
    hi = Math.min(hi, Math.max(xa, xb));
  } else if (b < ymin || b > ymax) return null;
  if (hi - lo < 1e-6) return null;
  return [{ x: lo, y: m * lo + b }, { x: hi, y: m * hi + b }];
