function halo(ctx, txt, x, y, color, align, baseline, fs, italic, bold) {
  ctx.save();
  ctx.font = (italic ? 'italic ' : '') + (bold ? 'bold ' : '') + fs.toFixed(1) + 'px sans-serif';
  ctx.textAlign = align; ctx.textBaseline = baseline;
  ctx.lineJoin = 'round'; ctx.strokeStyle = '#fff';
  ctx.lineWidth = Math.max(2, fs * 0.34);
