  dx /= L; dy /= L;
  var px = -dy, py = dx;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - dx * size + px * size * 0.45, y - dy * size + py * size * 0.45);
  ctx.lineTo(x - dx * size - px * size * 0.45, y - dy * size - py * size * 0.45);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
}

