  var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
  var S = Math.min(ca.width, ca.height);
  ctx.save();
  ctx.strokeStyle = '#d6d8da';
  ctx.lineWidth = Math.max(0.6, S * 0.0022);
  var i;
  for (i = -7; i <= 7; i++) { ctx.beginPath(); ctx.moveTo(X(i), Y(-5)); ctx.lineTo(X(i), Y(5)); ctx.stroke(); }
  for (i = -5; i <= 5; i++) { ctx.beginPath(); ctx.moveTo(X(-7), Y(i)); ctx.lineTo(X(7), Y(i)); ctx.stroke(); }
  // axes
  var aw = Math.max(1, S * 0.0038);
  var ah = Math.max(4, S * 0.019);
  ctx.strokeStyle = '#111'; ctx.lineWidth = aw;
  ctx.beginPath(); ctx.moveTo(X(-7.5), Y(0)); ctx.lineTo(X(7.5), Y(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(X(0), Y(-5.5)); ctx.lineTo(X(0), Y(5.5)); ctx.stroke();
  arrowHead(ctx, X(7.5), Y(0), 1, 0, ah, '#111');
  arrowHead(ctx, X(-7.5), Y(0), -1, 0, ah, '#111');
  arrowHead(ctx, X(0), Y(5.5), 0, -1, ah, '#111');
  arrowHead(ctx, X(0), Y(-5.5), 0, 1, ah, '#111');
  ctx.restore();
}

function drawOverlay(chart) {
  var ctx = chart.ctx, ca = chart.chartArea;
  var X = function (v) { return chart.scales.x.getPixelForValue(v); };
  var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
  var S = Math.min(ca.width, ca.height);
  var fs = Math.max(7.5, Math.min(14, S * 0.031));
  var ah = Math.max(4, S * 0.017);
  var gap = Math.max(3, S * 0.012);

  // axis letters
  halo(ctx, 'x', X(7.62), Y(0) - gap * 1.1, '#111', 'left', 'bottom', fs * 1.15, true, true);
  halo(ctx, 'y', X(0) + gap * 1.1, Y(5.62), '#111', 'left', 'top', fs * 1.15, true, true);

  // tick numbers (drawn on top of everything geometric, with halo)
  var i;
  for (i = -7; i <= 7; i++) {
    if (i === 0) continue;
    halo(ctx, fmt(i), X(i), Y(0) + gap, '#222', 'center', 'top', fs);
  }
  for (i = -5; i <= 5; i++) {
    if (i === 0) continue;
    halo(ctx, fmt(i), X(0) - gap, Y(i), '#222', 'right', 'middle', fs);
  }
  halo(ctx, '0', X(0) - gap, Y(0) + gap * 0.5, '#222', 'right', 'top', fs);

  // arrowheads + roman numerals for the four lines
  for (i = 0; i < LINES.length; i++) {
    var L = LINES[i];
    var seg = clipSeg(L.m, L.b, -6.9, 6.9, -5, 5);
    if (!seg) continue;
    var dim = FIG.sel && FIG.sel !== L.id;
    var col = dim ? rgba(L.color, 0.22) : L.color;
    var ax = X(seg[0].x), ay = Y(seg[0].y), bx = X(seg[1].x), by = Y(seg[1].y);
    arrowHead(ctx, bx, by, bx - ax, by - ay, ah, col);
    arrowHead(ctx, ax, ay, ax - bx, ay - by, ah, col);
    halo(ctx, L.id, X(L.lab.x), Y(L.lab.y), col, 'center', 'middle', fs * 1.1, false, true);
