  if (FIG.sel) drawStair(chart, figById(FIG.sel), X, Y, S, fs);

  // candidate line arrowheads + intercept dot
  var cs = clipSeg(FIG.m, FIG.b, -6.9, 6.9, -5, 5);
  if (cs) {
    var cax = X(cs[0].x), cay = Y(cs[0].y), cbx = X(cs[1].x), cby = Y(cs[1].y);
    arrowHead(ctx, cbx, cby, cbx - cax, cby - cay, ah * 0.9, MAG);
    arrowHead(ctx, cax, cay, cax - cbx, cay - cby, ah * 0.9, MAG);
