  ctx.save();
  ctx.setLineDash([d, d * 0.8]);
  ctx.lineWidth = Math.max(1, S * 0.0045);
  ctx.strokeStyle = L.color;
  ctx.beginPath();
  ctx.moveTo(X(x0), Y(y0)); ctx.lineTo(X(x1), Y(y0)); ctx.lineTo(X(x1), Y(y1));
  ctx.stroke();
  ctx.setLineDash([]);
  var r = Math.max(2.2, S * 0.011);
  ctx.fillStyle = L.color;
  ctx.beginPath(); ctx.arc(X(x0), Y(y0), r, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(X(x1), Y(y1), r, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
  halo(ctx, 'run = ' + fmt(run), (X(x0) + X(x1)) / 2, Y(y0) + Math.max(3, S * 0.011),
    L.color, 'center', 'top', fs * 0.95, false, true);
  halo(ctx, 'rise = ' + fmt(y1 - y0), X(x1) + Math.max(4, S * 0.014), (Y(y0) + Y(y1)) / 2,
    L.color, 'left', 'middle', fs * 0.95, false, true);
