function drawReadout(chart, X, Y, S, fs) {
  var ctx = chart.ctx;
  var rows = [{ t: 'candidate:  ' + eqStr(FIG.m, FIG.b), c: MAG, b: true }];
  var match = null, i;
  for (i = 0; i < LINES.length; i++) {
    if (Math.abs(LINES[i].m - FIG.m) < 1e-9 && Math.abs(LINES[i].b - FIG.b) < 1e-9) match = LINES[i];
  }
  if (match) rows.push({ t: '\u2713 matches line ' + match.id, c: match.color, b: true });
  if (FIG.sel) {
    var L = figById(FIG.sel);
    var rise = L.m * L.stair.run;
    rows.push({ t: 'line ' + L.id + ':  m = ' + fmt(rise) + '/' + fmt(L.stair.run) + ' = ' + fmt(L.m) + ',  b = ' + fmt(L.b), c: L.color, b: false });
    rows.push({ t: '\u2003' + eqStr(L.m, L.b), c: L.color, b: true });
  }
  var lh = fs * 1.35, padB = fs * 0.5;
  var w = 0;
  ctx.save();
  for (i = 0; i < rows.length; i++) {
    ctx.font = (rows[i].b ? 'bold ' : '') + fs.toFixed(1) + 'px sans-serif';
    w = Math.max(w, ctx.measureText(rows[i].t).width);
  }
  var x0 = X(-6.85), y0 = Y(-3.0);
  var boxW = w + padB * 2, boxH = rows.length * lh + padB * 1.6;
  ctx.fillStyle = 'rgba(255,255,255,0.9)';
  ctx.strokeStyle = 'rgba(0,0,0,0.16)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(x0, y0, boxW, boxH, fs * 0.35);
  else ctx.rect(x0, y0, boxW, boxH);
  ctx.fill(); ctx.stroke();
  ctx.restore();
  for (i = 0; i < rows.length; i++) {
    halo(ctx, rows[i].t, x0 + padB, y0 + padB * 0.8 + lh * i + lh * 0.5, rows[i].c, 'left', 'middle', fs, false, rows[i].b);
  }
}

