  var h = (H || cv.clientHeight || 500) - 2 * PAD;
  if (w <= 10 || h <= 10) return;
  var u = Math.min(w / 15.8, h / 11.8);
  var hx = w / (2 * u), hy = h / (2 * u);
  chart.options.scales.x.min = -hx; chart.options.scales.x.max = hx;
  chart.options.scales.y.min = -hy; chart.options.scales.y.max = hy;
}

function refresh() {
  var ca = chart.chartArea;
  var S = ca ? Math.min(ca.width, ca.height) : 400;
  var lw = Math.max(1.2, S * 0.0058);
  for (var i = 0; i < LINES.length; i++) {
    var L = LINES[i];
    var seg = clipSeg(L.m, L.b, -6.9, 6.9, -5, 5);
    var d = chart.data.datasets[i];
    d.data = seg || [];
    var dim = FIG.sel && FIG.sel !== L.id;
    d.borderColor = dim ? rgba(L.color, 0.22) : L.color;
    d.borderWidth = lw * (FIG.sel === L.id ? 1.9 : (FIG.hover === L.id ? 1.4 : 1));
  }
  var cs = clipSeg(FIG.m, FIG.b, -6.9, 6.9, -5, 5);
  var cd = chart.data.datasets[LINES.length];
  cd.data = cs || [];
  cd.borderWidth = lw * 1.15;
  cd.borderDash = [Math.max(4, S * 0.018), Math.max(3, S * 0.013)];
