/* ── hover / click hit testing on the canvas ──────────────────────── */
function distSeg(px, py, ax, ay, bx, by) {
  var dx = bx - ax, dy = by - ay;
  var L2 = dx * dx + dy * dy;
  var t = L2 ? ((px - ax) * dx + (py - ay) * dy) / L2 : 0;
  t = Math.max(0, Math.min(1, t));
  var qx = ax + t * dx, qy = ay + t * dy;
  return Math.hypot(px - qx, py - qy);
}

function hitTest(mx, my) {
  if (!chart.chartArea) return null;
  var sx = chart.scales.x, sy = chart.scales.y;
  var best = null;
  var bd = Math.max(6, Math.min(chart.chartArea.width, chart.chartArea.height) * 0.022);
  for (var i = 0; i < LINES.length; i++) {
    var L = LINES[i];
    var seg = clipSeg(L.m, L.b, -6.9, 6.9, -5, 5);
    if (!seg) continue;
    var d = distSeg(mx, my,
      sx.getPixelForValue(seg[0].x), sy.getPixelForValue(seg[0].y),
      sx.getPixelForValue(seg[1].x), sy.getPixelForValue(seg[1].y));
    if (d < bd) { bd = d; best = L; }
  }
  return best;
}

cv.addEventListener('mousemove', function (e) {
  var r = cv.getBoundingClientRect();
  var hit = hitTest(e.clientX - r.left, e.clientY - r.top);
  var id = hit ? hit.id : null;
  if (id !== FIG.hover) { FIG.hover = id; refresh(); }
  if (hit) {
    cv.style.cursor = 'pointer';
    showTooltip('Line ' + hit.id + ':  ' + eqStr(hit.m, hit.b) +
      '   (slope ' + fmt(hit.m) + ', y-intercept ' + fmt(hit.b) + ')', e);
  } else {
    cv.style.cursor = 'default';
    hideTooltip();
  }
});
cv.addEventListener('mouseleave', function () {
  hideTooltip();
  if (FIG.hover) { FIG.hover = null; refresh(); }
});
cv.addEventListener('click', function (e) {
  var r = cv.getBoundingClientRect();
  var hit = hitTest(e.clientX - r.left, e.clientY - r.top);
  if (hit) selectLine(hit.id); else { FIG.sel = null; syncChips(); refresh(); hidePopup(); }
});

/* ── demo step player ─────────────────────────────────────────────── */
function setSliderVal(id, v) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = v;
  if (out) out.value = v;
}

function setStep(i) {
  FIG.step = (i + STEPS.length) % STEPS.length;
  var s = STEPS[FIG.step];
  setSliderVal('candidateSlope', s.m);
  setSliderVal('candidateIntercept', s.b);
  FIG.m = s.m; FIG.b = s.b;
  FIG.sel = s.hl;
  syncChips();
  document.getElementById('demoNarration').textContent = s.t + ' — ' + s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (FIG.step + 1) + ' / ' + STEPS.length;
  refresh();
}
function nextStep() { setStep(FIG.step + 1); }
function prevStep() { setStep(FIG.step - 1); }

setStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Every line's equation y = mx + b is readable straight off its picture: the slope m controls direction and steepness, the intercept b controls where it crosses the y-axis, and together they uniquely identify which drawn line is which.
KEY INSIGHT (what students should walk away understanding): A line is pinned down by exactly two readable facts — how fast it rises (m) and where it crosses the y-axis (b) — so matching equations to graphs is never guesswork.
DEMO STEPS: 6 guided steps — implement the step player in #ui

